/* Mono Glass: ASCII Thinker drawn as live text, sharp at any resolution */
[data-workspace-area="conversation"], [data-slot="sidebar"] {
  background: #0a0612 !important;
}
[data-workspace-area="conversation"] {
  position: relative;
  isolation: isolate;
  background:
    radial-gradient(ellipse 60% 70% at 85% 60%, rgba(117,153,188,0.07), transparent 70%),
    #0a0612 !important;
}
[data-workspace-area="conversation"]::before,
[data-workspace-area="conversation"]::after {
  position: absolute;
  right: 2%;
  bottom: 0;
  z-index: -1;
  pointer-events: none;
  width: 61ch;
  white-space: break-spaces;
  word-break: break-all;
  overflow-wrap: anywhere;
  font-family: "JetBrains Mono", "SF Mono", Menlo, monospace;
  font-variant-ligatures: normal;
  font-size: min(1.44vh, 1.1vw);
  line-height: 1;
  letter-spacing: 0;
  text-align: left;
}
